+    private static CharSequence formatOf(short[] arr) {
+        StringBuilder b = new StringBuilder(arr.length*4);
+        HexFormat hex = HexFormat.of();
+        for (int j = 0; j<arr.length; j++) {
+            b.append(hex.toHexDigits(arr[j]));
+        }
+        return b.toString();
+    }
